-- pos-inventory: Flyway baseline (flattened 2026-09-09 from the previous migration history) with the
-- ADR-0062 tenancy schema folded in. Generated by scripts/db/tenancy/flatten.py from a pg_dump of a
-- database migrated with the retired scripts; the tenancy additions are mechanical and are listed in
-- docs/TENANCY_SCHEMA.md. Global (unscoped) tables: src/main/resources/db/tenancy-global-tables.txt.
--
-- Tenant context: app_current_tenant() reads the session setting app.current_tenant, which the
-- TenantAwareDataSource (pos-tenancy-common, plan WS1) binds per checkout. Until then the owner role
-- carries a transitional default (postgres/init-tenancy.sh) and tests set it per connection.
-- With nothing bound: NULL -> every scoped table reads as empty and refuses inserts (fail closed).

-- Functions are emitted before the tables they reference (pg_dump order); do not validate bodies.
SET check_function_bodies = false;

CREATE OR REPLACE FUNCTION public.app_current_tenant() RETURNS uuid
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$ SELECT NULLIF(current_setting('app.current_tenant', true), '')::uuid $$;

CREATE TABLE public.advance_shipping_notice (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    expected_arrival_date date,
    ship_date date,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    asn_id uuid NOT NULL,
    po_id uuid NOT NULL,
    vendor_id uuid NOT NULL,
    asn_reference_number character varying(255) NOT NULL,
    created_by character varying(255) NOT NULL,
    status character varying(255) NOT NULL,
    updated_by character varying(255),
    CONSTRAINT advance_shipping_notice_status_check CHECK (((status)::text = ANY (ARRAY[('LOADED'::character varying)::text, ('READY_FOR_RECEIPT'::character varying)::text, ('PARTIALLY_RECEIVED'::character varying)::text, ('FULLY_RECEIVED'::character varying)::text, ('CANCELLED'::character varying)::text])))
);

CREATE TABLE public.approval_threshold_config (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    active boolean NOT NULL,
    percentage_variance_threshold numeric(5,2) NOT NULL,
    unit_variance_threshold integer NOT NULL,
    value_variance_threshold numeric(19,2) NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    config_id uuid NOT NULL,
    approval_tier character varying(255) NOT NULL,
    flow_type character varying(30) DEFAULT 'CYCLE_COUNT'::character varying NOT NULL,
    CONSTRAINT approval_threshold_config_approval_tier_check CHECK (((approval_tier)::text = ANY (ARRAY[('TIER_1_MANAGER'::character varying)::text, ('TIER_2_DIRECTOR'::character varying)::text]))),
    CONSTRAINT approval_threshold_config_flow_type_check CHECK (((flow_type)::text = ANY (ARRAY[('CYCLE_COUNT'::character varying)::text, ('SCRAP'::character varying)::text, ('REVALUATION'::character varying)::text])))
);

CREATE TABLE public.asn_line (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    quantity_received numeric(18,6),
    quantity_shipped numeric(18,6) NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    unit_cost_minor bigint,
    asn_id uuid NOT NULL,
    asn_line_id uuid NOT NULL,
    po_id uuid NOT NULL,
    po_line_id uuid,
    lot_number character varying(255),
    sku character varying(255) NOT NULL,
    unit_of_measure character varying(255),
    document_uom character varying(32),
    document_quantity numeric(18,6),
    conversion_factor numeric(20,6)
);

CREATE TABLE public.backorder_record (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    backorder_id uuid NOT NULL,
    workorder_line_id uuid,
    sku character varying(255) NOT NULL,
    location_id uuid,
    quantity_short numeric(19,4) NOT NULL,
    status character varying(30) NOT NULL,
    resolution_source character varying(30),
    created_by character varying(255),
    created_ledger_entry_id uuid,
    resolved_ledger_entry_id uuid,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    resolved_at timestamp(6) with time zone,
    sales_order_line_id uuid,
    CONSTRAINT backorder_record_quantity_check CHECK ((quantity_short > (0)::numeric)),
    CONSTRAINT backorder_record_resolution_source_check CHECK (((resolution_source IS NULL) OR ((resolution_source)::text = ANY ((ARRAY['AVAILABILITY'::character varying, 'REPLENISHMENT_RECEIPT'::character varying, 'MANUAL'::character varying])::text[])))),
    CONSTRAINT backorder_record_status_check CHECK (((status)::text = ANY ((ARRAY['OPEN'::character varying, 'RESOLVED'::character varying, 'CANCELLED'::character varying])::text[]))),
    CONSTRAINT ck_backorder_record_one_demand_line CHECK (((workorder_line_id IS NOT NULL) <> (sales_order_line_id IS NOT NULL)))
);

CREATE TABLE public.cost_method_change_log (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    change_id uuid NOT NULL,
    scope_type character varying(32) NOT NULL,
    scope_value character varying(255),
    from_method character varying(32),
    to_method character varying(32),
    changed_by character varying(255) NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    change_type character varying(32) DEFAULT 'METHOD_SET'::character varying NOT NULL,
    CONSTRAINT cost_method_change_log_change_type_check CHECK (((change_type)::text = ANY ((ARRAY['METHOD_SET'::character varying, 'DEACTIVATED'::character varying, 'REACTIVATED'::character varying])::text[]))),
    CONSTRAINT cost_method_change_log_from_method_check CHECK (((from_method IS NULL) OR ((from_method)::text = ANY ((ARRAY['STANDARD'::character varying, 'AVERAGE'::character varying])::text[])))),
    CONSTRAINT cost_method_change_log_scope_type_check CHECK (((scope_type)::text = ANY ((ARRAY['SKU'::character varying, 'SKU_CATEGORY'::character varying, 'DEFAULT'::character varying])::text[]))),
    CONSTRAINT cost_method_change_log_to_method_check CHECK (((to_method IS NULL) OR ((to_method)::text = ANY ((ARRAY['STANDARD'::character varying, 'AVERAGE'::character varying])::text[])))),
    CONSTRAINT cost_method_change_log_to_method_required CHECK ((((change_type)::text = 'DEACTIVATED'::text) OR (to_method IS NOT NULL)))
);

CREATE TABLE public.count_entry (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    actual_quantity numeric(19,4) NOT NULL,
    expected_quantity numeric(19,4) NOT NULL,
    recount_sequence_number integer NOT NULL,
    variance numeric(19,4) NOT NULL,
    counted_at timestamp(6) with time zone NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    count_entry_id uuid NOT NULL,
    cycle_count_task_id uuid NOT NULL,
    recount_of_count_entry_id uuid,
    auditor_id character varying(100) NOT NULL,
    measured_quantity numeric(19,4) NOT NULL,
    uom_code character varying(32),
    measurement_method character varying(32) DEFAULT 'MANUAL_COUNT'::character varying NOT NULL,
    variance_percentage numeric(9,4),
    allowed_tolerance_absolute numeric(19,4),
    allowed_tolerance_percentage numeric(7,4),
    within_tolerance boolean DEFAULT false NOT NULL,
    variance_reason character varying(500)
);

CREATE TABLE public.cycle_count_adjustment (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    cost_at_time_of_adjustment numeric(19,4) NOT NULL,
    counted_quantity numeric(19,4) NOT NULL,
    quantity_change numeric(19,4) NOT NULL,
    quantity_on_hand_before numeric(19,4) NOT NULL,
    approved_at timestamp(6) with time zone,
    created_at timestamp(6) with time zone NOT NULL,
    posted_at timestamp(6) with time zone,
    rejected_at timestamp(6) with time zone,
    updated_at timestamp(6) with time zone NOT NULL,
    adjustment_id uuid NOT NULL,
    ledger_entry_id uuid,
    stock_item_id character varying(255) NOT NULL,
    rejection_reason character varying(1000),
    error_message character varying(2000),
    approved_by_user_id character varying(255),
    created_by_user_id character varying(255) NOT NULL,
    reason_code character varying(255) NOT NULL,
    rejected_by_user_id character varying(255),
    required_approval_tier character varying(255),
    status character varying(255) NOT NULL,
    task_id uuid,
    CONSTRAINT cycle_count_adjustment_required_approval_tier_check CHECK (((required_approval_tier)::text = ANY (ARRAY[('TIER_1_MANAGER'::character varying)::text, ('TIER_2_DIRECTOR'::character varying)::text]))),
    CONSTRAINT cycle_count_adjustment_status_check CHECK (((status)::text = ANY (ARRAY[('PENDING_APPROVAL'::character varying)::text, ('AUTO_APPROVED'::character varying)::text, ('APPROVED'::character varying)::text, ('POSTED'::character varying)::text, ('REJECTED'::character varying)::text, ('FAILED'::character varying)::text])))
);

CREATE TABLE public.cycle_count_plan (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    scheduled_date date NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    location_id uuid NOT NULL,
    plan_id uuid NOT NULL,
    status character varying(50) NOT NULL,
    created_by character varying(255) NOT NULL,
    plan_name character varying(255),
    schedule_id uuid,
    due_date date,
    CONSTRAINT cycle_count_plan_status_check CHECK (((status)::text = ANY (ARRAY[('PLANNED'::character varying)::text, ('STARTED'::character varying)::text, ('COMPLETED_PENDING_APPROVAL'::character varying)::text, ('APPROVED'::character varying)::text, ('REJECTED'::character varying)::text, ('CANCELLED'::character varying)::text])))
);

CREATE TABLE public.cycle_count_plan_zone (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
