CREATE TABLE public.cycle_count_schedule (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    schedule_id uuid NOT NULL,
    location_id uuid NOT NULL,
    zone_id uuid,
    sku_category character varying(100),
    frequency_days integer NOT NULL,
    next_due_date date NOT NULL,
    auto_create_plan boolean NOT NULL,
    active boolean NOT NULL,
    created_by character varying(255) NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    CONSTRAINT cycle_count_schedule_frequency_days_check CHECK ((frequency_days > 0))
);

CREATE TABLE public.cycle_count_task (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    count_entries_count integer NOT NULL,
    expected_quantity numeric(19,4) NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    latest_count_entry_id uuid,
    task_id uuid NOT NULL,
    status character varying(50) NOT NULL,
    auditor_id character varying(100) NOT NULL,
    bin_location character varying(100) NOT NULL,
    item_sku character varying(100) NOT NULL,
    item_description character varying(500),
    plan_id uuid,
    CONSTRAINT cycle_count_task_status_check CHECK (((status)::text = ANY (ARRAY[('ASSIGNED'::character varying)::text, ('COUNTED_PENDING_REVIEW'::character varying)::text, ('CONFLICT'::character varying)::text, ('REQUIRES_INVESTIGATION'::character varying)::text, ('APPROVED'::character varying)::text, ('REJECTED'::character varying)::text, ('ACCEPTED_WITHIN_TOLERANCE'::character varying)::text])))
);

CREATE TABLE public.cycle_count_tolerance (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    tolerance_id uuid NOT NULL,
    product_id uuid,
    storage_location character varying(100),
    absolute_tolerance numeric(19,4),
    percentage_tolerance numeric(7,4),
    active boolean DEFAULT true NOT NULL,
    created_by character varying(100) NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    CONSTRAINT cycle_count_tolerance_bounds_check CHECK ((((absolute_tolerance IS NULL) OR (absolute_tolerance >= (0)::numeric)) AND ((percentage_tolerance IS NULL) OR (percentage_tolerance >= (0)::numeric))))
);

CREATE TABLE public.distributor_feed_exception (
