    distributor_sku character varying(255),
    reason character varying(255) NOT NULL,
    CONSTRAINT distributor_feed_exception_reason_check CHECK (((reason)::text = ANY (ARRAY[('SKU_UNMAPPED'::character varying)::text, ('LEAD_TIME_UNPARSABLE'::character varying)::text, ('REGION_UNMAPPED'::character varying)::text, ('REGION_AMBIGUOUS'::character varying)::text, ('MALFORMED_DATA'::character varying)::text])))
);

