);

CREATE TABLE public.inventory_adjustment_request (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    quantity numeric(19,4) NOT NULL,
    approved_at timestamp(6) with time zone,
    created_at timestamp(6) with time zone NOT NULL,
    requested_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    adjustment_request_id uuid NOT NULL,
    location_id uuid NOT NULL,
    unit_of_measure character varying(50),
    reason_code character varying(100) NOT NULL,
    approved_by_user_id character varying(255),
    product_sku character varying(255) NOT NULL,
    requested_by_user_id character varying(255) NOT NULL,
    status character varying(255) NOT NULL,
    CONSTRAINT inventory_adjustment_request_status_check CHECK (((status)::text = ANY (ARRAY[('PENDING'::character varying)::text, ('APPROVED'::character varying)::text, ('REJECTED'::character varying)::text])))
);

CREATE TABLE public.inventory_allocation (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    allocated_quantity numeric(19,4) NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    hardened_at timestamp(6) with time zone,
    updated_at timestamp(6) with time zone NOT NULL,
    allocation_id uuid NOT NULL,
    location_id uuid,
    reservation_id uuid NOT NULL,
    allocation_state character varying(255) NOT NULL,
    hardened_by character varying(255),
    hardened_reason character varying(255),
    status character varying(255) NOT NULL,
    CONSTRAINT inventory_allocation_allocation_state_check CHECK (((allocation_state)::text = ANY (ARRAY[('SOFT'::character varying)::text, ('HARD'::character varying)::text]))),
    CONSTRAINT inventory_allocation_status_check CHECK (((status)::text = ANY (ARRAY[('ALLOCATED'::character varying)::text, ('PICKED'::character varying)::text, ('RELEASED'::character varying)::text])))
);

CREATE TABLE public.inventory_allocation_audit (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    occurred_at timestamp(6) with time zone NOT NULL,
    allocation_audit_id uuid NOT NULL,
