    CONSTRAINT inventory_allocation_audit_reason_code_check CHECK (((reason_code)::text = ANY (ARRAY[('SCHEDULE_CHANGE'::character varying)::text, ('PRIORITY_CHANGE'::character varying)::text, ('PRIORITY_AGED'::character varying)::text, ('MANUAL_OVERRIDE'::character varying)::text, ('STOCK_SHORTAGE'::character varying)::text, ('STOCK_REPLENISHED'::character varying)::text, ('LOCATION_CHANGE'::character varying)::text, ('WORK_ORDER_CANCELLED'::character varying)::text, ('WORK_ORDER_COMPLETED'::character varying)::text, ('SYSTEM_REBALANCE'::character varying)::text])))
);

CREATE TABLE public.inventory_ledger_entry (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    change_in_quantity numeric(19,4) NOT NULL,
    quantity_after numeric(19,4) NOT NULL,
    unit_cost numeric(19,4),
    created_at timestamp(6) with time zone NOT NULL,
    "timestamp" timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    adjustment_id uuid,
    from_location_id uuid,
    ledger_entry_id uuid NOT NULL,
    location_id uuid,
    to_location_id uuid,
    unit_of_measure character varying(50),
    reason_code character varying(100),
    notes character varying(2000),
    event_type character varying(255) NOT NULL,
    source_transaction_id character varying(255),
    stock_item_id character varying(255) NOT NULL,
    transaction_user_id character varying(255) NOT NULL,
    lot_id uuid,
    CONSTRAINT inventory_ledger_entry_event_type_check CHECK (((event_type)::text = ANY (ARRAY[('GOODS_RECEIPT'::character varying)::text, ('TRANSFER_IN'::character varying)::text, ('PUTAWAY'::character varying)::text, ('RETURN_TO_STOCK'::character varying)::text, ('ADJUSTMENT_IN'::character varying)::text, ('COUNT_VARIANCE_IN'::character varying)::text, ('GOODS_ISSUE'::character varying)::text, ('WORKORDER_CONSUMPTION'::character varying)::text, ('TRANSFER_OUT'::character varying)::text, ('SCRAP_OUT'::character varying)::text, ('ADJUSTMENT_OUT'::character varying)::text, ('COUNT_VARIANCE_OUT'::character varying)::text, ('ADJUST_CYCLE_COUNT'::character varying)::text, ('RESERVATION_CREATED'::character varying)::text, ('RESERVATION_RELEASED'::character varying)::text, ('ALLOCATION_CREATED'::character varying)::text, ('ALLOCATION_RELEASED'::character varying)::text, ('BACKORDER_CREATED'::character varying)::text, ('BACKORDER_RESOLVED'::character varying)::text, ('PICK_TASK_CREATED'::character varying)::text, ('PICK_TASK_COMPLETED'::character varying)::text])))
);

