    CONSTRAINT storage_compatibility_storage_category_code_check CHECK (((storage_category_code)::text = ANY ((ARRAY['TIRE_RACK'::character varying, 'OIL_STORAGE'::character varying, 'BATTERY_RACK'::character varying, 'SMALL_PARTS_BIN'::character varying, 'BULK_FLOOR'::character varying, 'GENERAL'::character varying])::text[])))
);

CREATE TABLE public.supplier_stock_hint (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    hint_id uuid NOT NULL,
    vendor_profile_id uuid NOT NULL,
    identity_kind character varying(20) NOT NULL,
    identity_value character varying(255) NOT NULL,
    article_ean character varying(64),
    supplier_article_code character varying(255),
    buyers_article_id character varying(255),
    description character varying(512),
    available_quantity integer,
    resolution_status character varying(20) NOT NULL,
    resolved_product_id uuid,
    resolved_at timestamp(6) with time zone,
    resolved_by character varying(64),
    source_snapshot_id uuid NOT NULL,
    source_chunk_sequence integer NOT NULL,
    supplier_ref character varying(255),
    snapshot_as_of timestamp(6) with time zone,
    as_of_source character varying(10) NOT NULL,
    fetched_at timestamp(6) with time zone NOT NULL,
    first_seen_at timestamp(6) with time zone NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    CONSTRAINT ck_supplier_stock_hint_as_of_source CHECK (((as_of_source)::text = ANY ((ARRAY['VENDOR'::character varying, 'FETCH'::character varying])::text[]))),
    CONSTRAINT ck_supplier_stock_hint_identity_kind CHECK (((identity_kind)::text = ANY ((ARRAY['EAN'::character varying, 'BUYER_ARTICLE'::character varying, 'SUPPLIER_ARTICLE'::character varying])::text[]))),
    CONSTRAINT ck_supplier_stock_hint_quantity CHECK (((available_quantity IS NULL) OR (available_quantity >= 0))),
    CONSTRAINT ck_supplier_stock_hint_resolution_status CHECK (((resolution_status)::text = ANY ((ARRAY['PENDING'::character varying, 'RESOLVED'::character varying, 'UNRESOLVED'::character varying, 'NOT_RESOLVABLE'::character varying])::text[])))
);

CREATE TABLE public.supplier_stock_snapshot_chunk (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    chunk_id uuid NOT NULL,
    snapshot_id uuid NOT NULL,
    chunk_sequence integer NOT NULL,
    lines_in_chunk integer NOT NULL,
    applied_at timestamp(6) with time zone NOT NULL,
    CONSTRAINT ck_supplier_stock_chunk_sequence CHECK ((chunk_sequence >= 1))
);

CREATE TABLE public.supplier_stock_snapshot_receipt (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    receipt_id uuid NOT NULL,
    snapshot_id uuid NOT NULL,
    vendor_profile_id uuid NOT NULL,
    supplier_ref character varying(255),
    document_id character varying(255),
    buyer_account_number character varying(64),
    chunk_count integer NOT NULL,
    chunks_applied integer NOT NULL,
    lines_reported integer NOT NULL,
    lines_applied integer NOT NULL,
    snapshot_as_of timestamp(6) with time zone,
    as_of_source character varying(10) NOT NULL,
    fetched_at timestamp(6) with time zone NOT NULL,
    complete boolean NOT NULL,
    first_chunk_at timestamp(6) with time zone NOT NULL,
    last_chunk_at timestamp(6) with time zone NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    CONSTRAINT ck_supplier_stock_receipt_as_of_source CHECK (((as_of_source)::text = ANY ((ARRAY['VENDOR'::character varying, 'FETCH'::character varying])::text[])))
);

CREATE TABLE public.transfer_order (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    transfer_order_id uuid NOT NULL,
    source_location_id uuid NOT NULL,
    source_storage_location_id uuid,
    destination_location_id uuid NOT NULL,
    destination_storage_location_id uuid,
    status character varying(30) NOT NULL,
    notes character varying(2000),
    created_by character varying(255) NOT NULL,
    approved_by character varying(255),
    dispatched_by character varying(255),
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    short_close_disposition character varying(30),
    short_close_reason character varying(100),
    short_close_notes character varying(2000),
    short_closed_by character varying(255),
    short_closed_at timestamp(6) with time zone,
    CONSTRAINT transfer_order_distinct_sites_check CHECK ((source_location_id <> destination_location_id)),
    CONSTRAINT transfer_order_short_close_disposition_check CHECK (((short_close_disposition IS NULL) OR ((short_close_disposition)::text = ANY ((ARRAY['LOST_IN_TRANSIT'::character varying, 'RETURNED_TO_SOURCE'::character varying])::text[])))),
    CONSTRAINT transfer_order_status_check CHECK (((status)::text = ANY (ARRAY[('DRAFT'::character varying)::text, ('APPROVED'::character varying)::text, ('DISPATCHED'::character varying)::text, ('PARTIALLY_RECEIVED'::character varying)::text, ('RECEIVED'::character varying)::text, ('SHORT_CLOSED'::character varying)::text, ('CANCELLED'::character varying)::text])))
);

CREATE TABLE public.transfer_order_line (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    line_id uuid NOT NULL,
    transfer_order_id uuid NOT NULL,
    line_number integer NOT NULL,
    sku character varying(255) NOT NULL,
    requested_qty integer NOT NULL,
    dispatched_qty integer DEFAULT 0 NOT NULL,
    received_qty integer DEFAULT 0 NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    lot_id uuid,
    lot_number character varying(128),
    CONSTRAINT transfer_order_line_qty_progress_check CHECK (((received_qty >= 0) AND (dispatched_qty >= received_qty) AND (requested_qty >= dispatched_qty))),
    CONSTRAINT transfer_order_line_requested_qty_check CHECK ((requested_qty > 0))
);

CREATE TABLE public.unmapped_manufacturer_part (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    occurrence_count integer NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    first_seen timestamp(6) with time zone NOT NULL,
    last_seen timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    id uuid NOT NULL,
    manufacturer_id uuid NOT NULL,
    manufacturer_part_number character varying(255) NOT NULL,
    status character varying(255) NOT NULL,
    CONSTRAINT unmapped_manufacturer_part_status_check CHECK (((status)::text = ANY (ARRAY[('PENDING_REVIEW'::character varying)::text, ('RESOLVED'::character varying)::text, ('IGNORED'::character varying)::text])))
);

CREATE TABLE public.warranty_part_return_hold (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    part_return_id uuid NOT NULL,
    claim_id uuid NOT NULL,
    claim_line_id uuid,
    product_entity_id uuid,
    serial_number character varying(128),
    disposition character varying(64),
    status character varying(32) NOT NULL,
    carrier character varying(64),
    tracking_number character varying(128),
    requested_at timestamp(6) with time zone,
    shipped_at timestamp(6) with time zone,
    aggregate_version bigint DEFAULT 0 NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL
);

